import Ajv, {type ErrorObject, type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

const AJV_OPTIONS = {strict: false, validateFormats: false} as never;

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  schemaValidator?: ValidateFunction;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaCompiler = new Ajv(AJV_OPTIONS);
  private readonly functionSchemaValidators = new WeakMap<Record<string, unknown>, ValidateFunction>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let schemaValidator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        schemaValidator = this.schemaCompiler.compile(resolved.inputSchema);
      } catch (error) {
        const detail = error instanceof Error ? error.message : String(error);
        throw new Error(`Invalid input schema for tool ${resolved.name}: ${detail}`, {cause: error});
      }
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, schemaValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validation contract: specs/hal-engine-tool-input-validation/spec.md */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const definition = this.resolveDefinition(tool.definitionSource);
    const schemaValidator = tool.schemaValidator ?? this.getFunctionSchemaValidator(definition.inputSchema);
    if (!schemaValidator(input)) {
      const error = schemaValidator.errors?.[0];
      const reason = this.formatValidationError(error);
      log.warn('tool', 'input validation failed', {name, reason});
      return {result: `Invalid tool input: ${reason}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }

  private getFunctionSchemaValidator(inputSchema: Record<string, unknown>): ValidateFunction {
    const cached = this.functionSchemaValidators.get(inputSchema);
    if (cached) return cached;
    const validator = this.schemaCompiler.compile(inputSchema);
    this.functionSchemaValidators.set(inputSchema, validator);
    return validator;
  }

  private formatValidationError(error: ErrorObject | undefined): string {
    if (!error) return 'does not match the declared schema';
    const details = error as ErrorObject & {
      instancePath?: string;
      dataPath?: string;
      params: {missingProperty?: string; type?: string; allowedValues?: unknown[]};
    };
    const path = details.instancePath ?? this.normalizeLegacyDataPath(details.dataPath);
    if (details.keyword === 'required') return `${path}/${String(details.params.missingProperty)} is required`;
    if (details.keyword === 'type') return `${path || '/'} must be ${String(details.params.type)}`;
    if (details.keyword === 'enum') {
      const allowedValues = this.formatAllowedValues(details.params.allowedValues);
      return `${path || '/'} must be one of ${allowedValues}`;
    }
    return `${path || '/'} fails ${details.keyword}`;
  }

  private formatAllowedValues(allowedValues: unknown[] | undefined): string {
    return allowedValues?.map(String).join(', ') ?? 'the declared values';
  }

  private normalizeLegacyDataPath(dataPath: string | undefined): string {
    if (!dataPath) return '';
    return `/${dataPath.replace(/^\./, '').replaceAll('.', '/')}`;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('returns a required-property rejection before invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'find_city',
        description: 'Finds a city by postal code',
        inputSchema: {
          type: 'object',
          properties: {postalCode: {type: 'string'}},
          required: ['postalCode'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'unreachable';
      }
    );

    const response = await registry.execute('find_city', {});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: 'Invalid tool input: /postalCode is required',
    });
  });

  it('passes valid undeclared properties through to the executor unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Berlin', units: 'metric'};
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'weather',
        description: 'Gets a forecast',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async receivedInput => {
        receivedInputs.push(receivedInput);
        return 'Forecast';
      }
    );

    await registry.execute('weather', input);

    expect(receivedInputs).toEqual([input]);
  });

  it('rejects a wrong-typed property before invoking the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'weather',
        description: 'Gets a forecast',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'unreachable';
      }
    );

    const response = await registry.execute('weather', {location: 12345});

    expect({executorCalls, result: response.result}).toEqual({
      executorCalls: 0,
      result: 'Invalid tool input: /location must be string',
    });
  });

  it('rejects an enum value with the allowed values', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'weather',
        description: 'Gets a forecast',
        inputSchema: {
          type: 'object',
          properties: {units: {enum: ['metric', 'imperial']}},
          required: ['units'],
        },
      },
      async () => 'unreachable'
    );

    const response = await registry.execute('weather', {units: 'kelvin'});

    expect(response.result).toBe('Invalid tool input: /units must be one of metric, imperial');
  });

  it('validates a function definition against the schema resolved for each call', async () => {
    let schema: Record<string, unknown> = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    const registry = new ToolRegistry();
    registry.register(
      () => ({name: 'weather', description: 'Gets a forecast', inputSchema: schema}),
      async () => 'Forecast'
    );

    schema = {type: 'object', properties: {postalCode: {type: 'string'}}, required: ['postalCode']};

    const response = await registry.execute('weather', {location: 'Berlin'});

    const validResponse = await registry.execute('weather', {postalCode: '10115'});

    expect({rejectedResult: response.result, validResponse}).toEqual({
      rejectedResult: 'Invalid tool input: /postalCode is required',
      validResponse: {result: 'Forecast'},
    });
  });

  it('reuses a static schema without rereading it during execution', async () => {
    let inputSchemaReads = 0;
    const definition = {
      name: 'weather',
      description: 'Gets a forecast',
      get inputSchema() {
        inputSchemaReads += 1;
        return {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        };
      },
    };
    const registry = new ToolRegistry();
    registry.register(definition, async () => 'Forecast');

    const response = await registry.execute('weather', {location: 'Berlin'});

    expect({inputSchemaReads, response}).toEqual({inputSchemaReads: 1, response: {result: 'Forecast'}});
  });

  it('throws unchanged for an unknown tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('missing_tool', {})).rejects.toThrow('Unknown tool: missing_tool');
  });
});
